import React from 'react';
import { Box } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { useTranslation } from 'react-i18next';

export const QURAN_VIEWS = ['read', 'words', 'mushaf'];

// Read, Words and Mushaf, as in the app: a gold-ruled segmented control whose
// active face slides under the chosen view.
const QuranViewSwitcher = ({ value, onChange }) => {
  const { t } = useTranslation('quran');
  const dark = useTheme().palette.mode === 'dark';
  const i = Math.max(0, QURAN_VIEWS.indexOf(value));
  const onKey = (e) => {
    const step = { ArrowRight: 1, ArrowLeft: -1 }[e.key];
    if (!step) return;
    e.preventDefault();
    const rtl = document.dir === 'rtl' ? -1 : 1;
    onChange(QURAN_VIEWS[(i + step * rtl + 3) % 3]);
  };
  return (
    <Box role="tablist" aria-label={t('views.label')} onKeyDown={onKey}
      sx={{
        position: 'relative', display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)',
        width: '100%', maxWidth: 420, mx: 'auto', p: '4px', borderRadius: 999,
        background: dark ? 'linear-gradient(180deg,#141E48,#0B1130)' : 'linear-gradient(180deg,#FFFDF8,#F7F1E3)',
        border: '1px solid', borderColor: dark ? 'rgba(226,193,90,.35)' : '#EADFC2',
        boxShadow: dark ? 'inset 0 1px 0 rgba(255,255,255,.05)' : 'inset 0 1px 0 #fff, 0 6px 24px rgba(138,101,16,.10)',
      }}>
      <Box aria-hidden sx={{
        position: 'absolute', top: 4, bottom: 4, insetInlineStart: 4,
        width: 'calc((100% - 8px) / 3)', borderRadius: 999,
        transform: `translateX(calc(${i * 100}% * var(--dir, 1)))`,
        '[dir="rtl"] &': { '--dir': -1 },
        transition: 'transform .35s cubic-bezier(.2,.8,.2,1)',
        background: 'linear-gradient(135deg,#FBE7A6 0%,#C99B2E 45%,#F3DC8E 70%,#A07A1C 100%)',
        boxShadow: '0 2px 10px rgba(201,155,46,.45), inset 0 1px 0 rgba(255,255,255,.6)',
        '@media (prefers-reduced-motion: reduce)': { transition: 'none' },
      }} />
      {QURAN_VIEWS.map((v, k) => (
        <Box key={v} component="button" type="button" role="tab" aria-selected={k === i}
          tabIndex={k === i ? 0 : -1} onClick={() => onChange(v)}
          sx={{
            position: 'relative', zIndex: 1, minHeight: 44, border: 0, background: 'none',
            cursor: 'pointer', borderRadius: 999, font: 'inherit', fontFamily: '"Marcellus", Georgia, serif',
            fontSize: 15, letterSpacing: '.04em', transition: 'color .25s',
            color: k === i ? '#3A2A05' : (dark ? '#E9DDB8' : '#5D6478'),
            fontWeight: k === i ? 600 : 400,
            '&:focus-visible': { outline: '2px solid #C99B2E', outlineOffset: 2 },
          }}>
          {t(`views.${v}`)}
        </Box>
      ))}
    </Box>
  );
};

export default QuranViewSwitcher;
