import React from 'react';
import { Box } from '@mui/material';
import { useTheme } from '@mui/material/styles';
import { parseTajweedText } from '../../utils/tajweedParser';

const toArabicDigits = (n) => String(n).replace(/\d/g, (d) => '٠١٢٣٤٥٦٧٨٩'[d]);

// The ayahs as one flowing, justified page inside an illuminated double frame,
// each ending on its ۝ number, as on a printed Mushaf. Tap an ayah to play it.
const MushafPage = ({ ayahs, settings, currentAyahNumber, onAyahClick }) => {
  const dark = useTheme().palette.mode === 'dark';
  const gold = dark ? '#E2C15A' : '#B38A2A';
  return (
    <Box sx={{
      position: 'relative', mx: 'auto', maxWidth: 820, p: { xs: '14px', sm: '22px' }, borderRadius: '6px',
      background: dark ? 'radial-gradient(120% 90% at 50% 0%,#18224F,#0B1130)' : 'radial-gradient(120% 90% at 50% 0%,#FFFDF6,#F6EEDA)',
      boxShadow: dark ? '0 20px 60px rgba(0,0,0,.45)' : '0 20px 60px rgba(138,101,16,.16)',
      border: `2px solid ${gold}`,
      '&::before': { content: '""', position: 'absolute', inset: { xs: 6, sm: 9 }, border: `1px solid ${gold}`, borderRadius: '3px', pointerEvents: 'none', opacity: .8 },
    }}>
      <Box dir="rtl" lang="ar" sx={{
        fontFamily: settings.fontFamily, fontSize: { xs: settings.fontSize * 0.95, sm: settings.fontSize * 1.1 },
        lineHeight: 2.35, textAlign: 'justify', textAlignLast: 'center', color: 'text.primary',
        px: { xs: 1, sm: 3 }, py: { xs: 1.5, sm: 2.5 },
      }}>
        {ayahs.map((ayah) => {
          const playing = currentAyahNumber === ayah.number;
          return (
            <Box key={ayah.number} component="span" role="button" tabIndex={0}
              aria-label={`Ayah ${ayah.numberInSurah}`}
              onClick={() => onAyahClick(ayah)}
              onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onAyahClick(ayah); } }}
              sx={{
                cursor: 'pointer', borderRadius: '6px', transition: 'background .2s',
                background: playing ? (dark ? 'rgba(226,193,90,.16)' : 'rgba(201,155,46,.14)') : 'transparent',
                '&:hover': { background: dark ? 'rgba(226,193,90,.08)' : 'rgba(201,155,46,.07)' },
                '&:focus-visible': { outline: `2px solid ${gold}` },
              }}>
              <span dangerouslySetInnerHTML={{ __html: parseTajweedText(ayah.tajweedText || ayah.text, settings.showTajweed, false) }} />
              <Box component="span" aria-hidden sx={{ color: gold, mx: '.25em', fontFamily: '"Amiri", serif', whiteSpace: 'nowrap' }}>
                {'۝'}{toArabicDigits(ayah.numberInSurah)}
              </Box>{' '}
            </Box>
          );
        })}
      </Box>
    </Box>
  );
};

export default MushafPage;
